from collections import deque
def regions(grid, dot):
    hh,ww=len(grid),len(grid[0])
    # cells of background NOT 4-connected to border without crossing a dot or non-background
    seen=set(); out=set()
    for i in range(hh):
        for j in range(ww):
            if grid[i][j]!=dot: continue
            if (i,j) in seen: continue
            comp=[]; q=deque([(i,j)]); seen.add((i,j)); touch=False
            while q:
                a,b=q.popleft(); comp.append((a,b))
                if a in(0,hh-1) or b in(0,ww-1): touch=True
                for da,db in((1,0),(-1,0),(0,1),(0,-1)):
                    na,nb=a+da,b+db
                    if 0<=na<hh and 0<=nb<ww and grid[na][nb]==dot and (na,nb) not in seen:
                        seen.add((na,nb)); q.append((na,nb))
            if not touch: out|=set(comp)
    return out
